import random, itertools, time

def trial(n,d,runs):
 Fs=[sum(1<<v for v in c) for c in itertools.combinations(range(n),d+1)]
 sub={F:[s for s in range(1<<n) if s&F==s] for F in Fs}
 ridges={F:[F^(1<<v) for v in range(n) if F>>v&1] for F in Fs}
 t=time.time()
 for run in range(runs):
  faces={0}; remain=set(Fs); order=[]
  # legal iff all old proper faces covered by old ridges
  while remain:
   choices=list(remain);random.shuffle(choices)
   for F in choices:
    oldR=[R for R in ridges[F] if R in faces]
    if not order or oldR and all(any(s&R==s for R in oldR) for s in sub[F] if s in faces):break
   else:
    print('TRAP',n,d,len(order),run,order,flush=True);return order
   order.append(F);remain.remove(F);faces.update(sub[F])
  if run%100==0: print(n,run,round(time.time()-t,2),flush=True)
 return None
for n in [7,8,9,10]:
 ans=trial(n,3,300)
 if ans: break

